UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0,0,0,E'<div>Los SAEE, que se integren en cualquiera de las modalidades descritas en el numeral 1.4, fracciones XXV a XXIX de las <br> Disposiciones, deben cumplir con las normas indicadas en la Tabla 1 o en la Tabla 2 siguientes, según corresponda:<br> <br> Tabla 1. Normas Internacionales <br><table> <tr> <td> <div> <span>IEC 62619</span><br/> </div> </td> </tr> <tr> <td> <div> <span>IEC 62933-5-1</span><br/> </div> </td> </tr> <tr> <td> <div> <span>IEC 62933-5-2</span><br/> </div> </td> </tr> </table><br><br> Tabla 2. Normas Extranjeras <br><table> <tr> <td> <div> <span>UL 1973</span><br/> </div> </td> </tr> <tr> <td> <div> <span>UL 9540</span><br/> </div> </td> </tr> </table><br><br> Las Normas mencionadas en la Tabla 1 y la Tabla 2 anteriores son aplicables en tanto no se emita la Norma Oficial <br> Mexicana en la materia. El cumplimiento debe demostrarse conforme a lo establecido en la Ley de Infraestructura de la <br> Calidad. </div>')) v(orden,inicio,largo,texto)) WHERE a.id='ec823410-ad59-4080-95d9-b21f24324621' AND md5(a.contenido)='939dff974f165012330ef1d06d3b1628' RETURNING a.id,md5(a.contenido) hash;